/**
 * The one place API shapes and local shapes meet.
 *
 * The generated types render the spec's `allOf` schemas as intersections
 * whose optional halves make required fields read as possibly undefined.
 * Mapping them here, field by field, keeps that quirk out of the rest of
 * the app: everything else deals in `@lexpad/core` shapes.
 */
import { asLanguage } from '@lexpad/core';
import type { Progress, Settings, Word } from '@lexpad/core';
import type {
  ApiAiJob,
  ApiAppNotification,
  ApiNotebook,
  ApiNotebookSchedule,
  ApiProgress,
  ApiSettings,
  ApiWord,
  ApiMeaning,
  ApiPhrase,
  ApiWordCreate,
} from '@/api/types.js';
import type { WordDraft } from '@/db/mutations.js';
import type {
  InboxNotification,
  StoredConfusion,
  StoredNotebook,
  StoredSchedule,
  StoredWord,
} from '@/db/schema.js';

const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'] as const;
type Level = (typeof LEVELS)[number];

function asLevel(value: string | undefined): Level | undefined {
  return LEVELS.find((level) => level === value);
}

const SOURCES = ['manual', 'ai', 'assistant', 'import', 'shared'] as const;
type Source = (typeof SOURCES)[number];

function asSource(value: string | undefined): Source {
  return SOURCES.find((source) => source === value) ?? 'manual';
}

/** The element types of the core word's collections, always as arrays. */
type CoreMeaning = NonNullable<Word['meanings']>[number];
type CorePhrase = NonNullable<Word['expressions']>[number];

function meanings(input: ApiMeaning[] | undefined): CoreMeaning[] {
  return (input ?? []).map((meaning) => ({
    meaning: meaning.meaning,
    ...(meaning.gloss === undefined ? {} : { gloss: meaning.gloss }),
    examples: (meaning.examples ?? []).map((example) => ({
      sentence: example.sentence,
      ...(example.translation === undefined ? {} : { translation: example.translation }),
    })),
  }));
}

function phrases(input: ApiPhrase[] | undefined): CorePhrase[] {
  return (input ?? []).map((phrase) => ({
    text: phrase.text,
    ...(phrase.translation === undefined ? {} : { translation: phrase.translation }),
  }));
}

/**
 * A timestamp in the one shape the local database stores: UTC with a `Z`.
 *
 * The server is meant to speak UTC, but a row the client stamped itself and
 * a row that arrived with an offset would otherwise sit side by side, and
 * the sort orders compare what is stored. Anything unparseable is kept as is
 * rather than turned into "Invalid Date".
 */
function iso(value: string): string {
  const ms = Date.parse(value);
  return Number.isNaN(ms) ? value : new Date(ms).toISOString();
}

/** A notification as the bell keeps it, with its instants canonicalised. */
export function notificationFromApi(input: ApiAppNotification): InboxNotification {
  return {
    id: input.id,
    kind: input.kind,
    title: input.title,
    body: input.body,
    ...(input.link === undefined || input.link === '' ? {} : { link: input.link }),
    createdAt: iso(input.createdAt),
    ...(input.readAt === undefined ? {} : { readAt: iso(input.readAt) }),
  };
}

/** Converts a word from the API into the row stored locally. */
export function wordFromApi(input: ApiWord): StoredWord {
  const stored: StoredWord = {
    id: input.id,
    notebookId: input.notebookId,
    headword: input.headword ?? '',
    category: input.category,
    source: asSource(input.source),
    position: input.position,
    createdAt: iso(input.createdAt),
    updatedAt: iso(input.updatedAt),
    meanings: meanings(input.meanings),
    expressions: phrases(input.expressions),
    collocations: input.collocations ?? [],
    relatedWords: phrases(input.relatedWords),
    relatedWordIds: input.relatedWordIds ?? [],
  };
  const level = asLevel(input.level);
  if (input.pos !== undefined) stored.pos = input.pos;
  if (level) stored.level = level;
  if (input.pronunciation !== undefined) stored.pronunciation = input.pronunciation;
  if (input.trickySpelling !== undefined) stored.trickySpelling = input.trickySpelling;
  if (input.spellingNote !== undefined) stored.spellingNote = input.spellingNote;
  if (input.originalMeaning !== undefined) stored.originalMeaning = input.originalMeaning;
  if (input.correction !== undefined) stored.correction = input.correction;
  if (input.usageNote !== undefined) stored.usageNote = input.usageNote;
  if (input.relatedNote !== undefined) stored.relatedNote = input.relatedNote;
  if (input.aiModel !== undefined) stored.aiModel = input.aiModel;
  return stored;
}

/** Converts a learning state from the API. */
export function progressFromApi(input: ApiProgress): Progress {
  const progress: Progress = {
    box: input.box,
    reps: input.reps,
    correct: input.correct,
    dueDay: input.dueDay,
    spellMisses: input.spellMisses,
    starred: input.starred,
    retired: input.retired,
    updatedAt: iso(input.updatedAt),
  };
  if (input.lastDay !== undefined) progress.lastDay = input.lastDay;
  if (input.memo !== undefined) progress.memo = input.memo;
  // The memory state is the server's; the client keeps a copy to show.
  if (input.stabilityE4 !== undefined) progress.stabilityE4 = input.stabilityE4;
  if (input.difficultyE4 !== undefined) progress.difficultyE4 = input.difficultyE4;
  if (input.lapses !== undefined) progress.lapses = input.lapses;
  if (input.lastLapseDay !== undefined) progress.lastLapseDay = input.lastLapseDay;
  return progress;
}

/** Converts one notebook's saved schedule settings from the API. */
export function scheduleFromApi(input: ApiNotebookSchedule): StoredSchedule {
  const schedule: StoredSchedule = {
    notebookId: input.notebookId,
    scheduler: input.scheduler,
    retention: input.retention,
    afterMiss: input.afterMiss,
    extraPractice: input.extraPractice,
    reviewCap: input.reviewCap,
    leechThreshold: input.leechThreshold,
    maxInterval: input.maxInterval,
    tuning: input.tuning,
    params: {
      w: input.params.w,
      source: input.params.source,
      ...(input.params.tunedAt === undefined ? {} : { tunedAt: iso(input.params.tunedAt) }),
      ...(input.params.reviews === undefined ? {} : { reviews: input.params.reviews }),
    },
  };
  if (input.updatedAt !== undefined) schedule.updatedAt = iso(input.updatedAt);
  return schedule;
}

/** Converts a notebook from the API. */
export function notebookFromApi(input: ApiNotebook): StoredNotebook {
  return {
    id: input.id,
    title: input.title,
    targetLang: asLanguage(input.targetLang),
    meaningLang: asLanguage(input.meaningLang, 'fa'),
    isDefault: input.isDefault,
    sortOrder: input.sortOrder ?? 0,
    role: input.role,
    wordCount: input.wordCount,
    createdAt: iso(input.createdAt),
    updatedAt: iso(input.updatedAt),
  };
}

/** Converts settings from the API, filling anything the server omitted. */
export function settingsFromApi(input: ApiSettings): Settings {
  const settings: Settings = {
    newPerDay: input.newPerDay,
    sessionCap: input.sessionCap,
    cardTypes: input.cardTypes,
    autoSpeak: input.autoSpeak,
    speakExamples: input.speakExamples,
    theme: input.theme,
    palette: input.palette,
    typedGrading: input.typedGrading,
    newWordOrder: input.newWordOrder,
    // Absent means the notebook being shown, which is the behaviour a
    // client that predates the setting already had.
    practiceScope: input.practiceScope ?? 'notebook',
    // Absent means on: a server or a device that predates the summary must
    // not read as somebody having turned it off.
    weeklySummary: input.weeklySummary ?? true,
    // Absent means on, for the same reason.
    pushNews: input.pushNews ?? true,
  };
  if (input.reminderTime !== undefined) settings.reminderTime = input.reminderTime;
  if (input.reminderTz !== undefined) settings.reminderTz = input.reminderTz;
  if (input.updatedAt !== undefined) settings.updatedAt = iso(input.updatedAt);
  return settings;
}

/** Converts settings to the API's shape for a push or a PUT. */
export function settingsToApi(settings: Settings): ApiSettings {
  const out: ApiSettings = {
    newPerDay: settings.newPerDay,
    sessionCap: settings.sessionCap,
    cardTypes: settings.cardTypes,
    autoSpeak: settings.autoSpeak,
    speakExamples: settings.speakExamples,
    theme: settings.theme,
    palette: settings.palette,
    typedGrading: settings.typedGrading,
    newWordOrder: settings.newWordOrder,
    practiceScope: settings.practiceScope,
    weeklySummary: settings.weeklySummary,
  };
  if (settings.reminderTime !== undefined) out.reminderTime = settings.reminderTime;
  if (settings.reminderTz !== undefined) out.reminderTz = settings.reminderTz;
  // A row from before the switch existed sends nothing, which the server reads as on.
  if (settings.pushNews !== undefined) out.pushNews = settings.pushNews;
  return out;
}

/** Converts a confusion pair from the API into its stored row. */
export function confusionFromApi(input: { wordA: string; wordB: string; count: number }): StoredConfusion {
  const [a, b] = input.wordA <= input.wordB ? [input.wordA, input.wordB] : [input.wordB, input.wordA];
  return { key: `${a}-${b}`, wordA: a, wordB: b, count: input.count };
}

/**
 * A generation job as the screens see it: a settled status, real arrays and
 * cards already shaped like the drafts the add mutation takes.
 */
export interface AiJobView {
  id: string;
  status: 'queued' | 'running' | 'done' | 'failed';
  error: string | undefined;
  cards: WordDraft[];
  usage: { cardsToday: number; dailyLimit: number } | undefined;
  /**
   * The words a partial request ("Many at once") will not fill, for the app
   * to save plain. Only on the answer that created the job; empty otherwise
   * and from a server that predates it.
   */
  plainWords: string[];
}

const AI_STATUSES = ['queued', 'running', 'done', 'failed'] as const;

function asStatus(value: string | undefined): AiJobView['status'] {
  return AI_STATUSES.find((status) => status === value) ?? 'queued';
}

/** Turns one generated card into the draft the add mutation takes. */
export function draftFromApi(input: ApiWordCreate): WordDraft {
  const [first, ...rest] = input.meanings ?? [];
  const example = first?.examples?.[0];
  const draft: WordDraft = {
    headword: input.headword ?? '',
    meaning: first?.meaning ?? '',
    category: input.category,
    source: asSource(input.source),
  };
  if (first?.gloss !== undefined) draft.gloss = first.gloss;
  if (example !== undefined) draft.example = example.sentence;
  if (example?.translation !== undefined) draft.translation = example.translation;
  // The flat fields hold the first sense's first example; its later
  // examples and every further sense ride along in the API's shape.
  const laterExamples = (first?.examples ?? []).slice(1);
  if (laterExamples.length > 0) draft.moreExamples = laterExamples;
  if (rest.length > 0) draft.extraMeanings = meanings(rest);
  if ((input.expressions ?? []).length > 0) draft.expressions = phrases(input.expressions);
  if ((input.collocations ?? []).length > 0) draft.collocations = input.collocations ?? [];
  if ((input.relatedWords ?? []).length > 0) draft.relatedWords = phrases(input.relatedWords);
  if (input.usageNote) draft.usageNote = input.usageNote;
  if (input.spellingNote) draft.spellingNote = input.spellingNote;
  if (input.correction) draft.correction = input.correction;
  if (input.pronunciation !== undefined) draft.pronunciation = input.pronunciation;
  if (input.pos !== undefined) draft.pos = input.pos;
  if (input.level !== undefined) draft.level = input.level;
  if (input.trickySpelling !== undefined) draft.trickySpelling = input.trickySpelling;
  return draft;
}

/** Converts a generation job from the API into the shape the screen renders. */
export function aiJobFromApi(input: ApiAiJob): AiJobView {
  const status = asStatus(input.status);
  return {
    id: input.id,
    status,
    error: input.error,
    cards: status === 'done' ? (input.cards ?? []).map(draftFromApi) : [],
    plainWords: (input.plainWords ?? []).filter(
      (word): word is string => typeof word === 'string' && word.trim() !== '',
    ),
    usage:
      input.usage === undefined
        ? undefined
        : {
            cardsToday: input.usage.cardsToday ?? 0,
            dailyLimit: input.usage.dailyLimit ?? 0,
          },
  };
}
