/**
 * The sync worker.
 *
 * Three operations, each idempotent and safe to interrupt:
 *
 * - **bootstrap** pulls the whole account once, after a first sign-in.
 * - **pull** applies the changes the server has recorded since our cursor.
 * - **push** drains the outbox in order. It never moves the cursor: the
 *   server's position after a push already includes what other devices sent
 *   in the meantime, and only a pull may skip past those.
 *
 * Nothing here blocks the UI. A failure leaves the outbox intact and the
 * cursor where it was, so the next attempt resumes rather than restarts.
 */
import type { Progress } from '@lexpad/core';
import { ApiError, isApiError } from '@/api/errors.js';
import { learn, sync as syncApi, words as wordsApi, type SyncSend } from '@/api/endpoints.js';
import type { ApiReviewEvent, ApiSyncChange, ApiSyncPushItem } from '@/api/types.js';
import { db, getMeta, setMeta, type OutboxItem, type LexpadDb, type UndoPayload } from '@/db/schema.js';
import { dropOutboxItems, parkOutboxItems, markOutboxAttempt, outboxItems } from '@/db/repo.js';
import { adoptServerStreak } from './streak.js';
import {
  confusionFromApi,
  notebookFromApi,
  progressFromApi,
  scheduleFromApi,
  settingsFromApi,
  wordFromApi,
} from './mapping.js';

/** How many outbox entries go in one push. */
export const PUSH_BATCH = 50;

/**
 * How many items the next push sends. A failed batch halves it, so a change
 * the server cannot take is isolated within a few rounds instead of taking
 * everything queued behind it down with it; a success doubles it back.
 */
let batchSize = PUSH_BATCH;

/** The current batch size, for tests. */
export function currentBatchSize(): number {
  return batchSize;
}

/** Back to the default, for tests. */
export function resetBatchSize(): void {
  batchSize = PUSH_BATCH;
}

/** Forces a batch size, for tests that need several rounds. */
export function setBatchSize(size: number): void {
  batchSize = Math.max(1, Math.min(PUSH_BATCH, size));
}

function shrinkBatch(): void {
  batchSize = Math.max(1, Math.floor(batchSize / 2));
}

function growBatch(): void {
  batchSize = Math.min(PUSH_BATCH, batchSize * 2);
}

/**
 * How many changes to ask for per pull page.
 *
 * The API caps `limit` at 200 and rejects anything larger outright, so a
 * bigger page does not mean fewer round trips, it means no pull at all.
 */
export const PULL_PAGE = 200;

/** After this many failures an item is parked so it cannot block the queue. */
export const MAX_ATTEMPTS = 6;

/** What one sync run did. */
export interface SyncOutcome {
  pushed: number;
  pulled: number;
  /** Items the server refused; they were dropped so the queue can drain. */
  rejected: number;
  cursor: string;
}

/** What a push did, and the failure that stopped it, if one did. */
export interface PushOutcome {
  pushed: number;
  rejected: number;
  /**
   * Set when a request failed in a way that is not the items' fault: the
   * network, an overloaded or broken server. Their work is still queued,
   * and the caller should wait before trying again rather than pull.
   */
  error?: Error;
  /** A server error on a batch of several: the batch was halved, try it again now. */
  shrunk?: boolean;
}

/** A thrown value as an Error, so it can be thrown again. */
function asError(error: unknown): Error {
  return error instanceof Error ? error : new Error('push failed');
}

/**
 * Whether a push failure says to stop and wait: nothing reached the server,
 * or it could not take anything just now. A refusal of the items themselves
 * is not one; those are counted against the items and the rest move on. A
 * server error on a batch of several is not one either: the batch halves
 * and goes again at once, so a change the server cannot take is isolated
 * in a few rounds; on a batch of one it is, since there is nothing left to
 * split.
 */
export function stopsTheRun(error: unknown, batch: number): boolean {
  if (!(error instanceof ApiError)) return true;
  if (error.kind === 'offline' || error.kind === 'tooMany' || error.busy) return true;
  if (error.kind === 'server') return batch <= 1;
  return false;
}

/** Replaces every local table with the server's view of the account. */
export async function bootstrap(database: LexpadDb = db): Promise<void> {
  const snapshot = await syncApi.snapshot();

  // The snapshot's collections are required by the contract, so no
  // defensive fallbacks: a server that omits one is a contract violation
  // and should fail loudly rather than silently produce an empty notebook.
  const words = snapshot.words.map(wordFromApi);
  const notebooks = snapshot.notebooks.map(notebookFromApi);
  const progress = snapshot.progress.map((row) => ({ wordId: row.wordId, ...progressFromApi(row) }));
  const confusions = snapshot.confusions.map(confusionFromApi);
  // Optional: a server from before SRS v2 phase B sends none.
  const schedules = (snapshot.schedules ?? []).map(scheduleFromApi);
  const dayStats = snapshot.history.map((stat) => ({
    day: stat.day,
    reviewed: stat.reviewed,
    correct: stat.correct,
    newWords: stat.newWords ?? 0,
  }));

  await database.transaction(
    'rw',
    [
      database.words,
      database.progress,
      database.notebooks,
      database.confusions,
      database.dayStats,
      database.meta,
      database.schedules,
    ],
    async () => {
      await Promise.all([
        database.words.clear(),
        database.progress.clear(),
        database.notebooks.clear(),
        database.confusions.clear(),
        database.dayStats.clear(),
        database.schedules.clear(),
      ]);
      await Promise.all([
        database.words.bulkPut(words),
        database.progress.bulkPut(progress),
        database.notebooks.bulkPut(notebooks),
        database.confusions.bulkPut(confusions),
        database.dayStats.bulkPut(dayStats),
        database.schedules.bulkPut(schedules),
      ]);
      await database.meta.bulkPut([
        { key: 'cursor', value: snapshot.cursor },
        { key: 'settings', value: settingsFromApi(snapshot.settings) },
        {
          key: 'streak',
          value: {
            current: snapshot.streak.current,
            longest: snapshot.streak.longest,
            ...(snapshot.streak.activeToday ? { lastActiveDay: todayFromSnapshot(snapshot.history) } : {}),
            // Streak freeze (SRS v2), when it is on: the server's last day,
            // freezes and covered days. Older servers send none of these, and
            // an account without freeze keeps exactly the old snapshot.
            ...(snapshot.streak.freezeOn === true
              ? {
                  ...(snapshot.streak.lastActiveDay === undefined
                    ? {}
                    : { lastActiveDay: snapshot.streak.lastActiveDay }),
                  freezeOn: true,
                  freezes: snapshot.streak.freezes ?? 0,
                  frozenDays: snapshot.streak.frozenDays ?? [],
                }
              : {}),
          },
        },
        {
          key: 'user',
          value: {
            id: snapshot.user.id,
            email: snapshot.user.email,
            displayName: snapshot.user.displayName,
            timezone: snapshot.user.timezone,
            locale: snapshot.user.locale,
          },
        },
        { key: 'lastSyncAt', value: new Date().toISOString() },
      ]);
    },
  );
}

/** The most recent day in the snapshot's history, for the streak. */
function todayFromSnapshot(history: { day: number }[]): number | undefined {
  if (history.length === 0) return undefined;
  return Math.max(...history.map((stat) => stat.day));
}

/** Applies one pulled change to the local tables. */
async function applyChange(change: ApiSyncChange, database: LexpadDb): Promise<void> {
  const payload = change.payload as Record<string, unknown> | undefined;

  // The one rule every branch follows: a pulled change never overwrites an
  // entity with a local edit still queued. The queued edit is newer than
  // anything the server can tell us; the push settles it, and the server's
  // answer comes back through a later pull.
  const queued = async (entity: string, entityId: string): Promise<boolean> =>
    (await database.outbox.where('[entity+entityId]').equals([entity, entityId]).count()) > 0;

  switch (change.entity) {
    case 'word':
      if (change.op === 'delete') {
        await database.words.delete(change.entityId);
        await database.progress.delete(change.entityId);
      } else if (payload && !(await queued('word', change.entityId))) {
        await database.words.put(wordFromApi(payload as never));
      }
      return;

    case 'progress':
      if (payload) {
        // A local edit, a grade or an undo of the same word is still queued.
        // Any of them is newer than what the server sent: a grade still on
        // its way would be shown undone for a moment, and an edit carries
        // the base the server needs to merge. Leave the word: the push
        // settles it, and a later pull brings the server's answer.
        if (!(await progressQueued(change.entityId, database))) {
          await database.progress.put({
            wordId: change.entityId,
            ...progressFromApi(payload as never),
          });
        }
      }
      return;

    case 'settings': {
      // A settings edit still waiting in the outbox is newer than anything
      // the server can tell us; the push will settle it. Same rule as
      // progress: a pulled change never overwrites a queued local one.
      if (await queued('settings', 'me')) return;
      if (payload) await database.meta.put({ key: 'settings', value: settingsFromApi(payload as never) });
      return;
    }

    case 'notebook':
      if (change.op === 'delete') {
        const ids = await database.words.where('notebookId').equals(change.entityId).primaryKeys();
        await Promise.all([
          database.notebooks.delete(change.entityId),
          database.words.bulkDelete(ids),
          database.progress.bulkDelete(ids),
        ]);
      } else if (payload && !(await queued('notebook', change.entityId))) {
        await database.notebooks.put(notebookFromApi(payload as never));
      }
      return;

    case 'confusion':
      if (payload) await database.confusions.put(confusionFromApi(payload as never));
      return;

    // One learner's schedule settings for one notebook. They are changed
    // only online, through PUT /notebooks/{id}/schedule, so nothing of them
    // is ever queued and the server's copy always wins.
    case 'schedule':
      if (change.op === 'delete') await database.schedules.delete(change.entityId);
      else if (payload) await database.schedules.put(scheduleFromApi(payload as never));
      return;
  }
}

/** Applies everything the server has recorded since our cursor. */
export async function pull(database: LexpadDb = db): Promise<{ pulled: number; cursor: string }> {
  let cursor = await getMeta('cursor', database);
  let pulled = 0;

  for (;;) {
    let page;
    try {
      page = await syncApi.pull(cursor, PULL_PAGE);
    } catch (error) {
      // A cursor older than the retained log means we must start over.
      if (isApiError(error, 'notFound')) {
        await bootstrap(database);
        return { pulled: 0, cursor: await getMeta('cursor', database) };
      }
      throw error;
    }

    if (page.changes.length > 0) {
      await database.transaction(
        'rw',
        [
          database.words,
          database.progress,
          database.notebooks,
          database.confusions,
          database.meta,
          database.outbox,
          database.schedules,
        ],
        async () => {
          for (const change of page.changes) await applyChange(change, database);
          await database.meta.put({ key: 'cursor', value: page.cursor });
        },
      );
      pulled += page.changes.length;
    }
    cursor = page.cursor;
    if (!page.hasMore) break;
  }

  await setMeta('lastSyncAt', new Date().toISOString(), database);
  return { pulled, cursor };
}

/** Whether a word has a progress edit, a grade or an undo still queued. */
async function progressQueued(wordId: string, database: LexpadDb, except?: number): Promise<boolean> {
  for (const entity of ['progress', 'review', 'undo'] as const) {
    const items = await database.outbox.where('[entity+entityId]').equals([entity, wordId]).toArray();
    if (items.some((item) => item.seq !== except)) return true;
  }
  return false;
}

/** One request's worth of the queue: a run of one kind of item, in order. */
interface Segment {
  kind: 'reviews' | 'changes' | 'undo';
  items: OutboxItem[];
}

/**
 * Cuts the queue into runs that each go in one request, keeping the order
 * the changes were made in. Order matters: a star made before a grade must
 * reach the server first, or the grade's token is stale; and an undo must
 * land after the grade it takes back and before any grade made after it.
 */
function segments(items: OutboxItem[]): Segment[] {
  const out: Segment[] = [];
  for (const item of items) {
    const kind = item.entity === 'review' ? 'reviews' : item.entity === 'undo' ? 'undo' : 'changes';
    const last = out[out.length - 1];
    if (last?.kind === kind && kind !== 'undo') last.items.push(item);
    else out.push({ kind, items: [item] });
  }
  return out;
}

/** Turns an outbox entry into the push item the API expects. */
function toPushItem(item: OutboxItem): ApiSyncPushItem {
  const push: ApiSyncPushItem = {
    clientId: item.clientId,
    entity: item.entity as ApiSyncPushItem['entity'],
    entityId: item.entityId,
    op: item.op,
    clientTs: item.clientTs,
  };
  if (item.baseCursor !== undefined) push.baseCursor = item.baseCursor;
  if (item.payload !== undefined) push.payload = item.payload as Record<string, unknown>;
  return push;
}

/**
 * Drains the outbox, oldest first, one run of one kind at a time. Review
 * events go to `/reviews`, an undo to `/progress/{wordId}` and sync entities
 * to `/sync/push`; all are idempotent by client id, so a retry after a lost
 * response is safe. A run that fails stops the push, so nothing overtakes it.
 */
export async function push(database: LexpadDb = db, send: SyncSend = {}): Promise<PushOutcome> {
  const items = await outboxItems(batchSize, database);
  const total: PushOutcome = { pushed: 0, rejected: 0 };
  for (const segment of segments(items)) {
    const run = segment.kind === 'reviews' ? pushReviews : segment.kind === 'undo' ? pushUndo : pushChanges;
    const result = await run(segment.items, database, send);
    total.pushed += result.pushed;
    total.rejected += result.rejected;
    if (result.failed) {
      if (stopsTheRun(result.error, segment.items.length)) total.error = asError(result.error);
      else if (isApiError(result.error, 'server')) total.shrunk = true;
      break;
    }
  }
  return total;
}

interface RunResult {
  pushed: number;
  rejected: number;
  failed: boolean;
  /** Why it failed, when it did. */
  error?: unknown;
}

/**
 * Marks reviews as sent before sending them, and reads them back: an undo
 * may have dropped one meanwhile, and a token may have been brought up to
 * date (`refreshTokens`). Undo uses the mark to know whether the server may
 * already have the review.
 */
async function claimReviews(items: OutboxItem[], database: LexpadDb): Promise<OutboxItem[]> {
  return database.transaction('rw', database.outbox, async () => {
    const fresh: OutboxItem[] = [];
    for (const item of items) {
      if (item.seq === undefined) continue;
      const current = await database.outbox.get(item.seq);
      if (current === undefined) continue;
      if (current.attempted !== true) await database.outbox.update(item.seq, { attempted: true });
      fresh.push(current);
    }
    return fresh;
  });
}

async function pushReviews(
  queuedReviews: OutboxItem[],
  database: LexpadDb,
  send: SyncSend,
): Promise<RunResult> {
  const reviews = await claimReviews(queuedReviews, database);
  if (reviews.length === 0) return { pushed: 0, rejected: 0, failed: false };
  let pushed = 0;
  let rejected = 0;
  const events = reviews.map((item) => item.payload as ApiReviewEvent);
  try {
    const result = await learn.submitReviews(events, send);
    const byClientId = new Map(result.results.map((entry) => [entry.clientId, entry.status]));
    const done: number[] = [];
    const refused: number[] = [];
    for (const item of reviews) {
      const status = byClientId.get((item.payload as ApiReviewEvent).clientId);
      if (status === undefined) continue;
      if (item.seq === undefined) continue;
      // "rejected" means the server will not take it as it is. It leaves
      // the queue so the rest can move, but it is parked, not deleted.
      if (status === 'rejected') {
        rejected++;
        refused.push(item.seq);
      } else {
        pushed++;
        done.push(item.seq);
      }
    }
    await dropOutboxItems(done, database);
    await parkOutboxItems(refused, database, 'rejected by the server');
    // Streak freeze: the server's streak is the judge once nothing is queued.
    await adoptServerStreak(result.streak, database);
    growBatch();
    return { pushed, rejected, failed: false };
  } catch (error) {
    await recordFailure(reviews, error, database);
    return { pushed, rejected, failed: true, error };
  }
}

async function pushChanges(changes: OutboxItem[], database: LexpadDb, send: SyncSend): Promise<RunResult> {
  let pushed = 0;
  let rejected = 0;
  try {
    const result = await syncApi.push(changes.map(toPushItem), send);
    const byClientId = new Map(result.results.map((entry) => [entry.clientId, entry]));
    const done: number[] = [];
    const refused: { seq: number; reason: string }[] = [];
    for (const item of changes) {
      const entry = byClientId.get(item.clientId);
      if (entry === undefined || item.seq === undefined) continue;
      if (entry.status === 'rejected') {
        // The server will not take it as it is. It leaves the queue so the
        // rest can move, but it is parked with the reason, not deleted:
        // the change exists nowhere else.
        rejected++;
        refused.push({ seq: item.seq, reason: entry.reason ?? 'rejected by the server' });
        continue;
      }
      pushed++;
      // A merge means the server's version won; adopt it locally.
      if (entry.status === 'merged' && entry.payload) {
        await adoptMerged(item, entry.payload, database);
      }
      done.push(item.seq);
    }
    await dropOutboxItems(done, database);
    for (const { seq, reason } of refused) await parkOutboxItems([seq], database, reason);
    // The cursor stays where the last pull left it. Taking the server's
    // position here would skip every change another device recorded
    // between the two, and those words would never arrive.
    growBatch();
    return { pushed, rejected, failed: false };
  } catch (error) {
    await recordFailure(changes, error, database);
    return { pushed, rejected, failed: true, error };
  }
}

/**
 * Sends one undo. The server answers with the word as it was before the
 * review; a review it never received is claimed so it is never applied. A
 * refusal (too old, or a later answer in the way) means the review stands:
 * the undo is dropped and the word is read back, so the screen shows what
 * the server has rather than the local guess.
 */
async function pushUndo([item]: OutboxItem[], database: LexpadDb, send: SyncSend): Promise<RunResult> {
  if (item?.seq === undefined) return { pushed: 0, rejected: 0, failed: false };
  const seq = item.seq;
  const undo = item.payload as UndoPayload;
  try {
    const answer = await learn.updateProgress(
      item.entityId,
      { op: 'undoReview', reviewClientId: undo.reviewClientId, clientTs: undo.clientTs },
      send,
    );
    await settleUndo(item, progressFromApi(answer), database);
    return { pushed: 1, rejected: 0, failed: false };
  } catch (error) {
    if (isApiError(error, 'notFound')) {
      // The word is gone; so is anything to undo.
      await settleUndo(item, undefined, database);
      return { pushed: 0, rejected: 1, failed: false };
    }
    if (isApiError(error, 'conflict')) {
      try {
        const word = await wordsApi.get(item.entityId);
        await settleUndo(item, word.progress ? progressFromApi(word.progress) : undefined, database);
        return { pushed: 0, rejected: 1, failed: false };
      } catch (readError) {
        // Kept, so the next sync asks again and reads the word then.
        await recordFailure([{ ...item, seq }], readError, database);
        return { pushed: 0, rejected: 0, failed: true, error: readError };
      }
    }
    await recordFailure([{ ...item, seq }], error, database);
    return { pushed: 0, rejected: 0, failed: true, error };
  }
}

/**
 * Drops a sent undo and takes the server's word for the state: adopted when
 * nothing else for the word is queued, and in any case handed to the grades
 * queued after the undo as the state they were made on.
 */
async function settleUndo(item: OutboxItem, server: Progress | undefined, database: LexpadDb): Promise<void> {
  const undo = item.payload as UndoPayload;
  await database.transaction('rw', [database.outbox, database.progress], async () => {
    if (item.seq !== undefined) await database.outbox.delete(item.seq);
    if (server === undefined) return;
    await refreshTokens(item.entityId, undo.restoredUpdatedAt, server.updatedAt, database);
    if (!(await progressQueued(item.entityId, database))) {
      await database.progress.put({ wordId: item.entityId, ...server });
    }
  });
}

/**
 * Brings the token of grades queued for a word up to date. A grade carries
 * the updatedAt of the state it was made on; when the server writes that
 * same state with a stamp of its own (an undo, a merged flag change), the
 * grade's token must become the server's stamp, or the server would refuse
 * the grade as made on an old copy.
 */
async function refreshTokens(
  wordId: string,
  localStamp: string,
  serverStamp: string,
  database: LexpadDb,
): Promise<void> {
  const reviews = await database.outbox.where('[entity+entityId]').equals(['review', wordId]).toArray();
  for (const review of reviews) {
    const payload = review.payload as ApiReviewEvent;
    if (review.seq === undefined || payload.seenUpdatedAt === undefined) continue;
    if (Date.parse(payload.seenUpdatedAt) !== Date.parse(localStamp)) continue;
    await database.outbox.update(review.seq, { payload: { ...payload, seenUpdatedAt: serverStamp } });
  }
}

/** Writes the server's merged version over ours. */
async function adoptMerged(
  item: OutboxItem,
  payload: Record<string, unknown>,
  database: LexpadDb,
): Promise<void> {
  switch (item.entity) {
    case 'word':
      await database.words.put(wordFromApi(payload as never));
      return;
    case 'progress': {
      const merged: Progress = progressFromApi(payload as never);
      const local = (item.payload as { updatedAt?: string } | undefined)?.updatedAt;
      if (local !== undefined) await refreshTokens(item.entityId, local, merged.updatedAt, database);
      if (!(await progressQueued(item.entityId, database, item.seq))) {
        await database.progress.put({ wordId: item.entityId, ...merged });
      }
      return;
    }
    case 'settings':
      await database.meta.put({ key: 'settings', value: settingsFromApi(payload as never) });
      return;
    case 'notebook':
      await database.notebooks.put(notebookFromApi(payload as never));
      return;
    default:
      return;
  }
}

/**
 * Deals with a batch the server did not take. Nothing queued is ever
 * deleted here: the learner's changes exist only locally until the server
 * has them.
 *
 * Only a failure the batch itself can explain counts against its items: a
 * 4xx other than the session or rate-limit kind, or a server error on a
 * batch of one that is not the server saying it is overloaded. The network being down, a session that needs refreshing,
 * a throttle or a server error on a larger batch are not the item's fault;
 * the batch just shrinks so a poisoned change is isolated. An item that
 * reaches MAX_ATTEMPTS is parked, not dropped, and Settings offers to retry.
 */
async function recordFailure(items: OutboxItem[], error: unknown, database: LexpadDb): Promise<void> {
  // An overloaded server took nothing and said so; nothing here is to blame.
  if (isApiError(error, 'offline') || (error instanceof ApiError && error.busy)) return;
  const message = error instanceof ApiError ? `${error.kind}: ${error.message}` : 'unknown error';
  const status = error instanceof ApiError ? error.status : 0;
  const clientFault = status >= 400 && status < 500 && status !== 401 && status !== 408 && status !== 429;
  const serverFaultOnOne = status >= 500 && items.length === 1;
  if (items.length > 1) shrinkBatch();
  if (!clientFault && !serverFaultOnOne) return;

  const parked: number[] = [];
  for (const item of items) {
    if (item.seq === undefined) continue;
    if (item.attempts + 1 >= MAX_ATTEMPTS) parked.push(item.seq);
    else await markOutboxAttempt(item.seq, message, database);
  }
  if (parked.length > 0) await parkOutboxItems(parked, database);
}

/**
 * Pushes until the queue is empty or a batch fails. One batch per sync was
 * not enough: a notebook of 1,700 words queued 35 batches, and at one batch
 * a minute the tab was closed long before they had all gone.
 *
 * A failure that is not the items' fault (`stopsTheRun`) ends the push at
 * once and comes back as `error`: after an outage, a client that kept
 * sending batch after batch into a server still recovering was part of what
 * kept it down. The sync loop waits before the next try.
 */
export async function pushAll(database: LexpadDb = db, send: SyncSend = {}): Promise<PushOutcome> {
  const total: PushOutcome = { pushed: 0, rejected: 0 };
  // The cap only guards against a bug; a real queue drains long before it.
  for (let round = 0; round < 1000; round++) {
    const result = await push(database, send);
    total.pushed += result.pushed;
    total.rejected += result.rejected;
    if (result.error !== undefined) {
      total.error = result.error;
      break;
    }
    if (result.pushed + result.rejected === 0 && result.shrunk !== true) break;
  }
  return total;
}

/**
 * Pushes everything queued, then pulls what is new. A push stopped by the
 * network or an overloaded server throws its error instead of pulling: the
 * pull would meet the same server, and the queue is still there to send.
 */
export async function syncOnce(database: LexpadDb = db): Promise<SyncOutcome> {
  const pushResult = await pushAll(database);
  if (pushResult.error !== undefined) throw pushResult.error;
  const pullResult = await pull(database);
  return {
    pushed: pushResult.pushed,
    rejected: pushResult.rejected,
    pulled: pullResult.pulled,
    cursor: pullResult.cursor,
  };
}

/** Whether the local database has been filled at least once. */
export async function isBootstrapped(database: LexpadDb = db): Promise<boolean> {
  return (await getMeta('lastSyncAt', database)) !== null;
}

/** Fills the local database if it is empty, then syncs. */
export async function ensureSynced(database: LexpadDb = db): Promise<void> {
  if (await isBootstrapped(database)) {
    await syncOnce(database);
    return;
  }
  await bootstrap(database);
}

/** What the sync loop asks of one run. */
export interface RunRequest {
  /**
   * Asked after the push, and only when it went through: whether to pull
   * as well. The loop answers from how long ago the last pull was.
   */
  shouldPull: () => Promise<boolean>;
  send?: SyncSend;
  /**
   * Pull even when the push failed: somebody pressed Sync now, and other
   * devices' changes can still arrive when only sending is failing. The
   * push's failure is still thrown afterwards.
   */
  pullAfterFailure?: boolean;
}

/**
 * One run of the sync loop (`sync/store.ts`): fills an empty database from
 * the snapshot, or pushes everything queued and then pulls if `shouldPull`
 * says so. A push the network or an overloaded server stopped throws, and
 * nothing is pulled. Says whether it pulled.
 */
export async function runSync(request: RunRequest, database: LexpadDb = db): Promise<{ pulled: boolean }> {
  if (!(await isBootstrapped(database))) {
    await bootstrap(database);
    return { pulled: true };
  }
  const pushed = await pushAll(database, request.send);
  if (pushed.error !== undefined) {
    if (request.pullAfterFailure === true) await pull(database).catch(() => undefined);
    throw pushed.error;
  }
  if (!(await request.shouldPull())) return { pulled: false };
  await pull(database);
  return { pulled: true };
}
